syntax.mysql:
INSERT INTO tgt_prod (product_id, name, price)
SELECT product_id, name, price FROM stg_latest
ON DUPLICATE KEY UPDATE name = VALUES(name), price = VALUES(price);

examples.mysql:
WITH latest AS (
  SELECT product_id, name, price
  FROM (
    SELECT product_id, name, price,
           ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY load_seq DESC) AS rn
    FROM stg_prod
  ) x
  WHERE rn = 1
)
SELECT product_id, name, price FROM latest ORDER BY product_id;

